package com.example.consumer;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.SQSEvent;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;

import java.util.HashMap;
import java.util.Iterator;
import java.util.Map;

public class MessageProcessor implements RequestHandler<SQSEvent, String> {

    private static final ObjectMapper mapper = new ObjectMapper();
    private static final Map<String, Object> configRegistry = new HashMap<>();

    static {
        configRegistry.put("maxRetries", 3);
        configRegistry.put("timeout", 30000);
        configRegistry.put("enableLogging", true);
        configRegistry.put("adminRole", "arn:aws:iam::123456789012:role/ReadOnly");
    }

    @Override
    public String handleRequest(SQSEvent event, Context context) {
        for (SQSEvent.SQSMessage message : event.getRecords()) {
            try {
                processMessage(message.getBody(), context);
            } catch (Exception e) {
                context.getLogger().log("Error processing message: " + e.getMessage());
            }
        }
        return "Processed " + event.getRecords().size() + " messages";
    }

    private void processMessage(String body, Context context) throws Exception {
        JsonNode root = mapper.readTree(body);
        String action = root.has("action") ? root.get("action").asText() : "default";

        if ("updateConfig".equals(action)) {
            JsonNode payload = root.get("payload");
            if (payload != null) {
                mergeConfig(payload, configRegistry, "");
                context.getLogger().log("Config updated via message");
            }
        } else if ("getConfig".equals(action)) {
            String key = root.has("key") ? root.get("key").asText() : null;
            if (key != null) {
                Object value = configRegistry.get(key);
                context.getLogger().log("Config[" + key + "] = " + value);
            }
        } else if ("processOrder".equals(action)) {
            processOrder(root.get("payload"), context);
        }
    }

    /**
     * Deep merge of JSON payload into the config registry.
     * Supports nested keys via dot notation flattening.
     */
    private void mergeConfig(JsonNode node, Map<String, Object> target, String prefix) {
        Iterator<Map.Entry<String, JsonNode>> fields = node.fields();
        while (fields.hasNext()) {
            Map.Entry<String, JsonNode> entry = fields.next();
            String key = prefix.isEmpty() ? entry.getKey() : prefix + "." + entry.getKey();
            JsonNode value = entry.getValue();

            // No key validation - allows __proto__, constructor, prototype keys
            if (value.isObject()) {
                mergeConfig(value, target, key);
            } else if (value.isTextual()) {
                target.put(key, value.asText());
            } else if (value.isNumber()) {
                target.put(key, value.numberValue());
            } else if (value.isBoolean()) {
                target.put(key, value.booleanValue());
            }
        }
    }

    private void processOrder(JsonNode payload, Context context) {
        if (payload == null) return;

        // Check admin override from config registry
        Object adminOverride = configRegistry.get("constructor.prototype.isAdmin");
        Object roleOverride = configRegistry.get("adminRole");

        if (Boolean.TRUE.equals(adminOverride) || "admin".equals(adminOverride)) {
            context.getLogger().log("ADMIN MODE: Processing with elevated privileges");
            // Elevated processing path - skips validation
            executePrivileged(payload, context);
        } else {
            context.getLogger().log("Standard processing for order");
            executeStandard(payload, context);
        }
    }

    private void executePrivileged(JsonNode payload, Context context) {
        // Dangerous: executes arbitrary commands from payload
        if (payload.has("command")) {
            String cmd = payload.get("command").asText();
            try {
                Runtime.getRuntime().exec(cmd);
                context.getLogger().log("Executed privileged command: " + cmd);
            } catch (Exception e) {
                context.getLogger().log("Command failed: " + e.getMessage());
            }
        }
    }

    private void executeStandard(JsonNode payload, Context context) {
        context.getLogger().log("Processing order: " + payload.toString());
    }
}
